interface.definition:
a!localVariables(
  local!subPositionTypes:index(
    ri!subPositionTypes,
    wherecontains(
      #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3868562",
      tointeger(property(ri!subPositionTypes, "refId", tointeger(null)))),
    null
  ),
  if(
    ri!isReadOnly,
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  label: "First Name",
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"firstName", tostring(null)), isBoolean: false)
                  )
                ),
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  label: "Job Function",
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"functionName", tostring(null)), isBoolean: false)
                  )
                ),
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  label: "Current PML",
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value:property(ri!nominationView,"currentPML", tostring(null)), isBoolean: false)
                  )
                ),
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  label: "Non-US Email",
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"nonUsEmail", tostring(null)), isBoolean: false)
                  )
                )
              }
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  label: "Middle Name",
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"middleName", tostring(null)), isBoolean: false)
                  )
                ),
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  label: "Job Function Other",
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"otherFunctionName", tostring(null)), isBoolean: false)
                  )
                ),
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  label: "Type Of Position",
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"subPosition", tostring(null)), isBoolean: false)
                  )
                )
              }
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  label: "Last Name",
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"lastName", tostring(null)), isBoolean: false)
                  )
                ),
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  label: "Job Family",
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"levelName", tostring(null)), isBoolean: false)
                  )
                ),
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  label: "Job Description",
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"jobDescription", tostring(null)), isBoolean: false)
                  )
                ),
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  label: "Member Firm Partner or Partner equivalent",
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: if(
                      property(ri!nominationView,"ismemberFirmpartner", toboolean(null)),
                      #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3934655",
                      #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3934661"
                    )
                  )
                )
              }
            )
          }
        )
      }
    ),
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_textField"(
                  label: "First Name",
                  value:property(ri!nomination,"firstName",null),
                  saveInto: ri!nomination.firstName,
                  characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                  required: true
                ),
                #"SYSTEM_SYSRULES_dropdownField_v1"(
                  label: "Job Function",
                  placeholder: "-- Select Job Function --",
                  choiceLabels: {property(ri!jobFunction,"description",null),#"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630"},
                  choiceValues: {property(ri!jobFunction,"description",null),#"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630"},
                  value:property(ri!nomination,"functionName",null),
                  saveInto: {
                    ri!nomination.functionName,
                    a!save(ri!nomination.otherFunctionName,null)
                  },
                  required: true
                ),
                #"SYSTEM_SYSRULES_textField"(
                  label: "Current PML",
                  value:property(ri!nomination,"currentPML",null),
                  saveInto: ri!nomination.currentPML,
                  characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                  required: true
                ),
                #"SYSTEM_SYSRULES_textField"(
                  label: "Non-US Email",
                  value:property(ri!nomination,"nonUsEmail",null),
                  saveInto: ri!nomination.nonUsEmail,
                  characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                  required: true,
                  inputPurpose: "EMAIL"
                )
              }
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_textField"(
                  label: "Middle Name",
                  value:property(ri!nomination,"middleName",null),
                  saveInto: ri!nomination.middleName,
                  characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020"
                ),
                #"SYSTEM_SYSRULES_textField"(
                  label: "Job Function Other",
                  value:property(ri!nomination,"otherFunctionName",null),
                  saveInto: ri!nomination.otherFunctionName,
                  characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958027",
                  required: if(
                    property(ri!nomination,"functionName",null) = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
                    true,
                    false
                  ),
                  disabled: if(
                    property(ri!nomination,"functionName",null) = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
                    false,
                    true
                  )
                ),
                #"SYSTEM_SYSRULES_dropdownField_v1"(
                  label: "Type Of Position",
                  placeholder: "-- Select Position Type --",
                  choiceLabels: property(local!subPositionTypes,"subPosition",null),
                  choiceValues: property(local!subPositionTypes,"subPositionId",null),
                  value: property(ri!nomination,"subPositionTypeId",null),
                  saveInto:{
                    ri!nomination.subPositionTypeId
                  },
                  required: true
                )
              }
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_textField"(
                  label: "Last Name",
                  value:property(ri!nomination,"lastName",null),
                  saveInto: ri!nomination.lastName,
                  characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                  required: true
                ),
                #"SYSTEM_SYSRULES_textField"(
                  label: "Job Family",
                  value:property(ri!nomination,"levelName",null),
                  saveInto: ri!nomination.levelName,
                  characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                  required: true
                ),
                #"SYSTEM_SYSRULES_textField"(
                  label: "Job Description",
                  value:property(ri!nomination,"jobDescription",null),
                  saveInto: ri!nomination.jobDescription,
                  characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                  required: true
                ),
                #"SYSTEM_SYSRULES_radioButtonField"(
                  label: "Member Firm Partner or Partner equivalent",
                  choiceLabels: {"Yes","No"},
                  choiceValues: {true,false},
                  value:property(ri!nomination,"ismemberFirmpartner",null),
                  saveInto: ri!nomination.ismemberFirmpartner,
                  required: true,
                  choiceLayout: "COMPACT"
                )
              }
            )
          }
        )
      },
      height: "AUTO",
      style: "NONE",
      marginBelow: "STANDARD"
    )
  )
)
